    n_vars = len(vars_)
    if n_vars == 0:
        return {}

    max_group_size = max(1, n_vars // 3)
    n_groups = max(4, (n_vars + max_group_size - 1) // max_group_size)
    base = n_vars // n_groups
    rem = n_vars % n_groups

    groups: dict[str, list[str]] = {}
    start = 0
    for k in range(n_groups):
