    vals: dict[str, float] = {}
    for i in range(n_items):
        for t in range(n_periods):
            vals[f"x_{i}_{t}"] = float(pulp.value(x2[i, t]) or 0.0)
            vals[f"inv_{i}_{t}"] = float(pulp.value(inv2[i, t]) or 0.0)
            vals[f"unmet_{i}_{t}"] = float(pulp.value(unmet2[i, t]) or 0.0)
